Method.Source:
/**
 * Extends the customer account statement controller to populate the
 * customer transaction description for sales invoices and sales credit notes.
 *
 * The description is determined using the customer's industry key and the
 * configured customer statement description setup. For sales invoices,
 * the method falls back to the MET OSC code when no configured description
 * is available or when an industry key is not found.
 */
protected void populateCustAccountStatementExtTmp(int _custCurrencyIndex)
{
    next populateCustAccountStatementExtTmp(_custCurrencyIndex);

    if (cust_Trans)
    {
        if(currentTrans.Invoice && currentTrans.TransType ==LedgerTransType::Sales)
        {
            SalesTable salesTable = METCustActivityStatementController::findSalesTableFromCustTrans(currentTrans.AccountNum, currentTrans.Voucher, currentTrans.Invoice, currentTrans.TransDate);

            if (salesTable.SalesId)
            {
                METCustStmtIndustryKey  industryKey     = METCustActivityStatementController::getIndustryKey(salesTable.SalesId);
                METCustStmtTransType    stmtTransType   = salesTable.SalesType == SalesType::Sales ? METCustStmtTransType::SalesInvoice : METCustStmtTransType::SalesCreditNote;

                if (industryKey)
                {
                    custAccountStatementExtTmp.CustTrans_Txt    = METCustStmtDescriptionSetup::find(stmtTransType, industryKey).DefaultDescription;

                    if (!custAccountStatementExtTmp.CustTrans_Txt && stmtTransType == METCustStmtTransType::SalesInvoice)
                    {
                        SalesLine salesLine                         = SalesLine::find(salesTable.SalesId);
                        custAccountStatementExtTmp.CustTrans_Txt    = salesLine.displayMETOSCCode();
                    }
                }
                else if (stmtTransType == METCustStmtTransType::SalesInvoice)
                {
                    SalesLine salesLine                         = SalesLine::find(salesTable.SalesId);
                    custAccountStatementExtTmp.CustTrans_Txt    = salesLine.displayMETOSCCode();
                }
            }
        }
    }
}
